package com.example.rokidkeyboardbridge;
import android.content.*;import android.content.res.*;import android.graphics.*;import org.json.*;import java.io.*;import java.lang.reflect.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;
public final class VirtualContactDeviceChecks {
 static int n;static void ok(boolean b,String s){n++;if(!b)throw new AssertionError(s);}
 static Method method(Class<?> c,String name,Class<?>...types)throws Exception{Method m=c.getDeclaredMethod(name,types);m.setAccessible(true);return m;}
 static void field(Object o,String name,Object v)throws Exception{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);f.set(o,v);}
 static void write(File p,String text)throws Exception{try(FileOutputStream out=new FileOutputStream(p)){out.write(text.getBytes(StandardCharsets.UTF_8));}}
 public static int run(Context c,String source)throws Exception{
  c.getSharedPreferences("virtual_contact",0).edit().clear().commit();VirtualContactSession scene=new VirtualContactSession(c);scene.user("こんにちは");ok(c.getSharedPreferences("virtual_contact",0).getString("state","").isEmpty(),"ordinary conversation does not create a contact record");scene.clear();ok(scene.block("今日の天気は？").isEmpty(),"ordinary reset does not invent a contact scene");scene.user("手を差し出して");ok(scene.frame().kind==1,"session offer");ok(scene.gesture(0),"session accepts tap");scene.user("あたたかいね");ok(scene.frame().kind==2,"session retains state on conversation");
  VirtualContactPolicy.Frame held=scene.frame();ok(held==scene.frame(),"cached frame no allocations");String encrypted=c.getSharedPreferences("virtual_contact",0).getString("state","");ok(!encrypted.isEmpty()&&!encrypted.contains("HAND")&&!encrypted.contains("手を"),"stored encrypted enum state");VirtualContactSession restored=new VirtualContactSession(c);ok(restored.frame().kind==2&&restored.frame().actor==3,"encrypted restore");
  MainActivity activity=new MainActivity();method(ContextWrapper.class,"attachBaseContext",Context.class).invoke(activity,c);field(activity,"sharedMemoryManager",new SharedMemoryManager(c,()->"{}"));Field budget=MainActivity.class.getDeclaredField("diagnosticGeminiBudget");budget.setAccessible(true);((java.util.concurrent.atomic.AtomicInteger)budget.get(activity)).set(0);field(activity,"virtualContactSession",scene);
  long now=System.currentTimeMillis();SharedPreferences prefs=c.getSharedPreferences("gemini_settings",0);JSONArray history=new JSONArray().put(new JSONObject().put("time",now).put("user","手を差し出して").put("assistant","手を差し出して待っています。ユーザーはまだ手を取っていません。").put("topic","general"));prefs.edit().clear().putString("conversation_history",history.toString()).putLong("last_conversation_at",now).commit();
  String current="そのままそばにいて。今は私と手をつないでいる？ 今の状態に沿って一文で返事をしてください。検索や外部操作はしないでください。";scene.user(current);field(activity,"activeGeminiPrompt",current);String prompt=(String)method(MainActivity.class,"buildGeminiPromptCompact",String.class,boolean.class).invoke(activity,current,true);ok(prompt.contains("virtual_contact_state")&&prompt.contains("\"state\":\"HAND\""),"actual normal prompt includes current hold despite older offered history");
  Method build=method(MainActivity.class,"buildConversationRequest",JSONObject.class,Integer.class,String.class);capture(c,activity,build,prompt,"provider-contact-hold.json");field(activity,"voiceLoopMode",true);String voice=(String)method(MainActivity.class,"buildGeminiPromptCompact",String.class,boolean.class).invoke(activity,current,true);ok(voice.contains("voice_conversation_policy")&&voice.contains("\"state\":\"HAND\""),"VOICE same state");field(activity,"voiceLoopMode",false);
  prefs.edit().clear().commit();
  for(int i=0;i<2;i++){if(i==1){JSONArray synthetic=new JSONArray().put(new JSONObject().put("time",now).put("user","ねそべって").put("assistant","椅子に座った状態で表示しています。").put("topic","general"));prefs.edit().putString("conversation_history",synthetic.toString()).putLong("last_conversation_at",now).commit();}String posture=i==0?"ねそべって":"ねそべらないな";scene.user(posture);field(activity,"activeGeminiPrompt",posture);String pp=(String)method(MainActivity.class,"buildGeminiPromptCompact",String.class,boolean.class).invoke(activity,posture,true);ok(pp.contains("requested_pose=LYING")&&(i==0||pp.contains("DISPLAY_REPAIR")),"actual request includes supported posture");capture(c,activity,build,pp,"provider-poised-"+i+".json");}
  scene.user("手を離して");scene.user("今は手をつないでいる？");ok(scene.frame().kind==0,"status question does not restart scene after release");String released="手を離した今の状態について、一文で返事をしてください。以前の描写へ戻らず、検索や外部操作はしないでください。";scene.user(released);field(activity,"activeGeminiPrompt",released);String releasePrompt=(String)method(MainActivity.class,"buildGeminiPromptCompact",String.class,boolean.class).invoke(activity,released,true);ok(releasePrompt.contains("\"state\":\"NONE\""),"release beats old transcript");capture(c,activity,build,releasePrompt,"provider-contact-release.json");ok(new VirtualContactSession(c).frame().kind==0,"release persisted");
  scene.user("手を握る");scene.user("今日の天気を教えて");ok(!scene.frame().visible()&&scene.block("今日の天気を教えて").isEmpty(),"task remains ordinary");ok(scene.block("手を握る方法という仕様は？").isEmpty(),"explanation is not virtual touch request");scene.clear();c.getSharedPreferences("virtual_contact",0).edit().clear().commit();visuals(c,source);return n;
 }
 static void capture(Context c,MainActivity activity,Method build,String prompt,String name)throws Exception{
  JSONObject input=new JSONObject().put("contents",new JSONArray().put(new JSONObject().put("role","user").put("parts",new JSONArray().put(new JSONObject().put("text",prompt)))));JSONObject body=(JSONObject)build.invoke(activity,input,null,null);body.remove("tools");body.remove("toolConfig");write(new File(c.getFilesDir(),name),body.toString());
 }
 static void visuals(Context c,String source)throws Exception{
  AssetManager assets=AssetManager.class.getConstructor().newInstance();AssetManager.class.getMethod("addAssetPath",String.class).invoke(assets,source);Resources resources=new Resources(assets,c.getResources().getDisplayMetrics(),c.getResources().getConfiguration());Context imageContext=new ContextWrapper(c){public AssetManager getAssets(){return assets;}public Resources getResources(){return resources;}};
  Bitmap raw;try(InputStream in=assets.open(FullBodyGestureRenderer.assetForClip(22))){raw=BitmapFactory.decodeStream(in);}int split=FullBodyGestureRegions.split(raw),cw=raw.getWidth()/4;int[] sourcePixels=new int[raw.getWidth()*raw.getHeight()];raw.getPixels(sourcePixels,0,raw.getWidth(),0,0,raw.getWidth(),raw.getHeight());for(int row=0;row<2;row++)for(int col=0;col<4;col++){boolean clear=true;for(int y=row==0?0:split;y<(row==0?split:raw.getHeight());y++)for(int x=0;x<Math.max(3,cw/32);x++){int left=sourcePixels[y*raw.getWidth()+col*cw+x]&0xffffff,right=sourcePixels[y*raw.getWidth()+(col+1)*cw-1-x]&0xffffff;if((left&255)>32||(right&255)>32)clear=false;}ok(clear,"raw sprite column clearance: "+row+"/"+col);}raw.recycle();
  FullBodyGestureCanvasTest.Host host=new FullBodyGestureCanvasTest.Host(imageContext);FullBodyGestureRenderer body=new FullBodyGestureRenderer(host);PortraitExpressionRenderer face=new PortraitExpressionRenderer(imageContext);ok(face.ready(),"portrait loaded");Bitmap montage=Bitmap.createBitmap(240*4,920*2,Bitmap.Config.ARGB_8888);Canvas sheet=new Canvas(montage);sheet.drawColor(Color.BLACK);long time=System.currentTimeMillis();
  for(int posture=0;posture<2;posture++){int clip=22+posture;host.done=new CountDownLatch(1);body.request(clip);ok(host.done.await(15,TimeUnit.SECONDS)&&body.ready(clip),"contact atlas decodes bounded");Set<Integer> hashes=new HashSet<>();for(int pose=0;pose<4;pose++){
   int kind=pose+1;VirtualContactPolicy.Frame state=new VirtualContactPolicy.Frame(kind,kind==4?2:1,kind==4?2:3,2,pose,2,time,pose+1,false,kind==1);face.virtualContact(state,time+400);body.contactPose(VirtualContactPresentation.frame(state),VirtualContactPresentation.pulse(state,time+400));
   Bitmap fb=Bitmap.createBitmap(240,320,Bitmap.Config.ARGB_8888),bb=Bitmap.createBitmap(240,600,Bitmap.Config.ARGB_8888);Canvas fc=new Canvas(fb),bc=new Canvas(bb);fc.drawColor(Color.BLACK);bc.drawColor(Color.BLACK);ok(face.draw(fc,240,320,0,0,false,false,10000+pose*2000),"contact face draw");ok(body.draw(bc,240,600,clip,1200,10000+pose*2000),"contact body draw");int[] pixels=new int[240*600];bb.getPixels(pixels,0,240,0,0,240,600);hashes.add(Arrays.hashCode(pixels));int bottom=0,count=0;boolean edge=true;for(int y=0;y<600;y++)for(int x=0;x<240;x++){if((pixels[y*240+x]&0xffffff)!=0){bottom=Math.max(bottom,y);count++;if(x<3||x>=237)edge=false;}}ok(count>1500&&bottom>=586&&bottom<=594,"contact silhouette visible with shared floor and clipping");sheet.drawBitmap(fb,pose*240,posture*920,null);sheet.drawBitmap(bb,pose*240,posture*920+320,null);fb.recycle();bb.recycle();
  }ok(hashes.size()==4,"offer/hold/hug/pat visibly distinct per posture");}
  FullBodyMascotView view=new FullBodyMascotView(imageContext);Field affection=FullBodyMascotView.class.getDeclaredField("affectionCue");affection.setAccessible(true);FullBodyAffectionCue legacy=(FullBodyAffectionCue)affection.get(view);legacy.user("手をつないで",10000);legacy.answer("手をそっと握り返します。",FullBodyPoseCatalog.Kind.SHY,10001);ok(legacy.clip(10002,true)>=0,"legacy contact active before release");view.cancelContactGestures();ok(legacy.clip(10003,true)<0,"release cancels legacy scene so it cannot replay");face.rapport.preview(10000);face.clearContactCues();ok(!face.rapport.active(10001),"release cancels portrait acknowledgement");
  body.release();ok(!body.ready(22)&&!body.ready(23),"new caches released");face.release();try(FileOutputStream out=new FileOutputStream(new File(c.getFilesDir(),"contact-preview.png"))){montage.compress(Bitmap.CompressFormat.PNG,100,out);}montage.recycle();
 }
}
